<script module lang="ts">
/**
 * Menubar.Submenu: a row that opens a list of its own, one level deep.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menubar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext } from 'svelte'

import * as zag from '@zag-js/menu'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  attributes,
  followHighlight,
  joinSlot,
  mergeParts,
  normalizeProps,
  returnFocus,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/menubar.module.css'
import Kbd from '../structure/Kbd.svelte'
import type { MenuEntry } from './Menu.svelte'

export interface MenubarSubmenuProps {
  entry: MenuEntry
}
</script>

<script lang="ts">
let { entry }: MenubarSubmenuProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
const owner: Record<string, any> = getContext('polymorph:Menubar') ?? {}
let panel = $state<HTMLElement | null>(null)
let row = $state<HTMLElement | null>(null)
const items = $derived(entry.kind === 'submenu' ? entry.items : [])
const documentDirection = useDirection(() => row)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      positioning: { placement: 'right-start', gutter: 2 },
      onSelect: (details) => {
        items.forEach(
          (item) => 'onSelect' in item && item.label === details.value && item.onSelect(),
        )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const present = usePresence(
  () => api.open,
  () => panel,
)
const effect1 = () => {
  ;(owner.api?.setChild(service), api.setParent(owner.service))
}
watchEffect(effect1)
const effect2 = () => {
  followHighlight(panel, api.highlightedValue)
}
watchEffect(effect2, { watch: () => api.highlightedValue })
const effect3 = () => {
  api.open || returnFocus(row, panel)
}
watchEffect(effect3, { watch: () => api.open, mount: false })
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if entry.kind === 'submenu'
    }{#if entry.disabled
      }<div
        {...attributes(owner.api?.getItemProps({ value: entry.label, disabled: true }) ?? {})}
        class={styles.item}
        data-tone="neutral"
        >{#if entry.icon !== undefined
          }<span class={styles.glyph}><Icon name={entry.icon} size="sm" /></span
        >{/if
        }<span class={styles.label}>{entry.label}</span
        ><span class={styles.hint}><Icon name="next" size="sm" /></span
      ></div
    >{:else
      }<div
        bind:this={row}
        {...attributes(owner.api?.getTriggerItemProps(api) ?? {})}
        class={styles.item}
        data-tone="neutral"
        tabindex="-1"
        >{#if entry.icon !== undefined
          }<span class={styles.glyph}><Icon name={entry.icon} size="sm" /></span
        >{/if
        }<span class={styles.label}>{entry.label}</span
        ><span class={styles.hint}><Icon name="next" size="sm" /></span
      ></div
    >{/if
    }<Portal
      >{#if present.current
        }<div {...attributes(api.getPositionerProps())}
          ><div
            bind:this={panel}
            {...attributes(mergeParts(api.getContentProps(), { onKeydownCapture: (event: KeyboardEvent) => { typeof owner.handOff === 'function' && owner.handOff(event, api) } }))}
            class={styles.content}
            style:--radix-dropdown-menu-content-available-height={'var(--available-height)'}
            style:--radix-dropdown-menu-content-transform-origin={'var(--transform-origin)'}
            hidden={undefined}
            >{#each items as entry, index (index)
              }{#if entry.kind === 'separator'
                }<div {...attributes(api.getSeparatorProps())} class={styles.separator}></div
              >{:else if entry.kind === 'label'
                }<div class={styles.groupLabel}>{entry.label}</div
              >{:else if entry.kind === 'checkbox'
                }<div
                  {...attributes(mergeParts(api.getOptionItemProps({ type: 'checkbox', value: entry.label, checked: entry.checked, disabled: entry.disabled, closeOnSelect: false, onCheckedChange: entry.onCheckedChange }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={[styles.item, styles.checkbox]}
                  tabindex="-1"
                  ><span class={styles.check}
                    >{#if entry.checked}<Icon name="confirm" size="sm" />{/if
                  }</span
                  ><span class={styles.label}>{entry.label}</span
                ></div
              >{:else
                }<div
                  {...attributes(mergeParts(api.getItemProps({ value: entry.label, disabled: entry.disabled }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={styles.item}
                  data-tone={entry.tone ?? 'neutral'}
                  tabindex="-1"
                  >{#if entry.icon !== undefined
                    }<span class={styles.glyph}><Icon name={entry.icon} size="sm" /></span
                  >{/if
                  }<span class={styles.label}>{entry.label}</span
                  >{#if entry.kbd !== undefined
                    }<span class={styles.hint}><Kbd>{entry.kbd}</Kbd></span
                  >{/if
                }</div
              >{/if
            }{/each
          }</div
        ></div
      >{/if
    }</Portal
  >{/if
}{/if
}{@render joined.end?.()}
